import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getPostHandler } from "../handlers/getPostHandler";
import type { ApiError } from "../runtime/client";
import type { FeedPartition } from "../types/FeedPartition";

type Data = Awaited<ReturnType<typeof getPostHandler>>;

export function useGetPost(
  postId: FeedPartition,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getPost", postId],
    queryFn: () => getPostHandler(postId),
    ...options,
  });
}
